int error_code = 101;
const wchar_t* msg = L"Resource acquisition failed.";

// Outputting wide string literals (L"...")
// and mixed types to the standard error stream.
std::wcerr << L"Error (" << error_code
           << L"): " << msg
           << std::endl;
// std::wcerr is automatically tied to std::wcout.
// Flushes automatically when writing to stderr.
